public class ScalarWriteProbe62 {
    private static Map<String, Object> putText(Object input) {
        ScalarWrite__c record = new ScalarWrite__c(Name = 'sentinel', TextValue__c = 'before');
        Map<String, Object> row = new Map<String, Object>();
        String stage = 'before-put';
        try {
            stage = 'calling-put';
            record.put('TextValue__c', input);
            stage = 'assigned';
            row.put('success', true);
        } catch (Exception error) {
            row.put('success', false);
            row.put('exceptionType', error.getTypeName());
            row.put('exceptionMessage', error.getMessage());
        }
        Object stored = record.get('TextValue__c');
        row.put('stage', stage);
        row.put('storedJSON', JSON.serialize(stored));
        row.put('isString', stored instanceof String);
        row.put('isDate', stored instanceof Date);
        row.put('isNull', stored == null);
        row.put('preservedSeedName', record.Name);
        return row;
    }

    private static Map<String, Object> putDate() {
        ScalarWrite__c record = new ScalarWrite__c(Name = 'sentinel', DateValue__c = Date.newInstance(2024, 6, 7));
        Map<String, Object> row = new Map<String, Object>();
        String stage = 'before-put';
        Object input = Date.newInstance(2025, 1, 2);
        try {
            stage = 'calling-put';
            record.put('DateValue__c', input);
            stage = 'assigned';
            row.put('success', true);
        } catch (Exception error) {
            row.put('success', false);
            row.put('exceptionType', error.getTypeName());
            row.put('exceptionMessage', error.getMessage());
        }
        Object stored = record.get('DateValue__c');
        row.put('stage', stage);
        row.put('storedJSON', JSON.serialize(stored));
        row.put('isString', stored instanceof String);
        row.put('isDate', stored instanceof Date);
        row.put('isNull', stored == null);
        row.put('preservedSeedName', record.Name);
        return row;
    }

    public static String observe() {
        return JSON.serialize(new Map<String, Object>{
            'dateToText' => putText(Date.newInstance(2025, 1, 2)),
            'stringToText' => putText('after'),
            'nullToText' => putText(null),
            'dateToDate' => putDate()
        });
    }
}

